const story=document.querySelector('.robot-story'),boards=[...document.querySelectorAll('.board')];const motionBoard=document.querySelector('#motion');motionBoard.dataset.height='1400';function fit(){const s=story.clientWidth/1920;boards.forEach(b=>{b.style.height=(+b.dataset.height*s)+'px';b.querySelector('.board-inner').style.transform=`scale(${s})`})}new ResizeObserver(fit).observe(story);fit();const box=document.querySelector('#original-lightbox');let last;document.addEventListener('click',e=>{const image=e.target.closest('[data-image]');if(image){last=image;box.querySelector('img').src=image.dataset.image;box.showModal();return}if(e.target.closest('[data-zoom]')){document.body.classList.toggle('expanded');e.target.closest('button').setAttribute('aria-label',document.body.classList.contains('expanded')?'适应窗口':'放大展板');fit()}if(e.target.closest('[data-motion]')){const b=e.target.closest('button'),frame=document.querySelector('iframe');try{const doc=frame.contentDocument,c=doc.querySelector('.original-canvas');c.classList.toggle('motion-paused');b.textContent=c.classList.contains('motion-paused')?'播放动效':'暂停动效'}catch{b.textContent='请在独立窗口体验'}}});box.querySelector('.close').addEventListener('click',()=>box.close());box.addEventListener('click',e=>{if(e.target===box)box.close()});box.addEventListener('close',()=>last?.focus());
